document.addEventListener("DOMContentLoaded", function () {
  const container = document.querySelector('#allproductsfilter');
  if (!container) return;

  const parentSelect = container.querySelector('.jet-select__control.depth-0');
  const childWrapper = container.querySelector('.jet-select__control.depth-1')?.closest('.jet-select');

  // Oculta o segundo filtro ao carregar
  if (childWrapper) {
    childWrapper.style.display = 'none';
  }

  parentSelect?.addEventListener('change', function () {
    const observer = new MutationObserver(() => {
      const childSelect = container.querySelector('.jet-select__control.depth-1');
      if (!childSelect || !childWrapper) return;

      const hasOptions = Array.from(childSelect.options).some(
        (option) => option.value !== ''
      );

      childWrapper.style.display = hasOptions ? 'block' : 'none';
    });

    observer.observe(container, {
      childList: true,
      subtree: true,
    });

    setTimeout(() => observer.disconnect(), 2000);
  });
});
